        return 1 if n == 1 else 0
    if n == 1:
        return 1 if m == 0 else 0

    # dp[i][j] will store the number of ways to be at position j after i passes
    dp = [[0] * n for _ in range(m + 1)]

    # Initial condition: starting at position 0 with 0 passes
    dp[0][0] = 1

    # Fill the dp table
    for i in range(1, m + 1):
        for j in range(n):
            # The ball can come to the current position from the left or right neighbor
