def count_coprime_pairs(x0: int, y0: int) -> int:
    import math

    # If x0 is 0 or y0 is 0, or if x0 does not divide y0, no pairs can exist
    if x0 == 0 or y0 == 0 or y0 % x0 != 0:
        return 0

    # Calculate the quotient
    quotient = y0 // x0

    # Initialize the count of coprime pairs
    count = 0

    # Iterate through all possible factors 'a' of 'quotient'
    for a in range(1, int(math.sqrt(quotient)) + 1):
        if quotient % a == 0:
            b = quotient // a
            # Check if 'a' and 'b' are co-prime
            if math.gcd(a, b) == 1:
                if a == b:
                    count += 1
                else:
                    count += 2

    return count

